public static void removeAll(Queue<Integer> q, int x) {
    Queue<Integer> temp = new Queue<Integer>();
    while (!q.isEmpty()) {
        int y = q.remove();
        if (y != x) {
            temp.insert(y);
        }
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
}

public static Queue<Integer> reverse(Queue<Integer> q) {
    Stack<Integer> s = new Stack<Integer>();
    Queue<Integer> temp = new Queue<Integer>();
    while (!q.isEmpty()) {
        int x = q.remove();
        s.push(x);
        temp.insert(x);
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    Queue<Integer> result = new Queue<Integer>();
    while (!s.isEmpty()) {
        result.insert(s.pop());
    }
    return result;
}

