public static void RemoveAll(Queue<int> q, int x)
{
    Queue<int> temp = new Queue<int>();
    while (!q.IsEmpty())
    {
        int y = q.Remove();
        if (y != x)
        {
            temp.Insert(y);
        }
    }
    while (!temp.IsEmpty())
    {
        q.Insert(temp.Remove());
    }
}

public static Queue<int> Reverse(Queue<int> q)
{
    Stack<int> s = new Stack<int>();
    Queue<int> temp = new Queue<int>();
    while (!q.IsEmpty())
    {
        int x = q.Remove();
        s.Push(x);
        temp.Insert(x);
    }
    while (!temp.IsEmpty())
    {
        q.Insert(temp.Remove());
    }
    Queue<int> result = new Queue<int>();
    while (!s.IsEmpty())
    {
        result.Insert(s.Pop());
    }
    return result;
}

